sctp_disposition_t sctp_handle_dup_cookie_echo(
    struct net *net,
    const struct sctp_endpoint *ep,
    const struct sctp_association *asoc,
    sctp_subtype_t type,
    void *arg,
    sctp_cmd_seq_t *commands)
{
    sctp_chunk_t *chunk = (sctp_chunk_t *)arg;
    sctp_cookie_echo_t *cookie;
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;
    int error;

    if (chunk->chunk_hdr->length < sizeof(sctp_cookie_echo_t) + sizeof(sctp_param_hdr_t)) {
        return SCTP_DISPOSITION_DROP;
    }

    cookie = (sctp_cookie_echo_t *)chunk->skb->data;

    if (sctp_unpack_state_cookie(asoc, cookie->cookie, ntohs(cookie->cookie->length), &error) < 0) {
        if (error == -ENOMEM) {
            disposition = SCTP_DISPOSITION_NOMEM;
        } else if (asoc->c.sinit_num_ostreams == 0) {
            sctp_cmd_init(commands, SCTP_CMD_INIT, SCTP_SUCCESS);
        } else {
            disposition = SCTP_DISPOSITION_DROP;
        }
        return disposition;
    }

    if (asoc->c.sctp_vtag != ntohs(chunk->subh->cookie_hdr->verification_tag)) {
        sctp_cmd_init(commands, SCTP_CMD_RESTART_ASSOC, SCTP_SUCCESS);
    } else {
        sctp_cmd_init(commands, SCTP_CMD_HB, SCTP_SUCCESS);
    }

    return disposition;
}

sctp_disposition_t sctp_handle_cookie_echo_dup(struct net *net, const struct sctp_endpoint *ep,
                                              const struct sctp_association *asoc,
                                              sctp_subtype_t type, void *arg,
                                              sctp_cmd_seq_t *commands)
{
    sctp_chunk_t *chunk = (sctp_chunk_t *)arg;
    sctp_cookie_echo_t *cookie_echo;
    sctp_disposition_t retval = SCTP_DISPOSITION_CONSUME;
    int error = 0;

    if (chunk->skb->len < sizeof(*cookie_echo)) {
        return SCTP_DISPOSITION_BAD;
    }

    cookie_echo = (sctp_cookie_echo_t *)chunk->skb->data;

    if (sctp_unpack_cookie(net, ep, asoc, cookie_echo, chunk->skb->len) < 0) {
        return SCTP_DISPOSITION_NOMEM;
    }

    if (asoc->verified_tag != sctp_get_tag_from_cookie(cookie_echo)) {
        sctp_cmd_sf(commands, SCTP_CMD_COOKIE_ECHO_COLLISION, SCTP_NULL);
        return SCTP_DISPOSITION_NOMEM;
    }

    if (asoc->state != SCTP_STATE_COOKIE_ECHOED) {
        sctp_cmd_sf(commands, SCTP_CMD_NEW_ASOC, SCTP_NULL);
    }

    return retval;
}

sctp_disposition_t sctp_handle_cookie_echo(struct net *net, const struct sctp_endpoint *ep,
                                          const struct sctp_association *asoc, sctp_subtype_t type,
                                          void *arg, sctp_cmd_seq_t *commands)
{
    sctp_chunkhdr_t *chunk = arg;
    sctp_cookie_echo_t *cookie;
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;
    int error = 0;

    if (ntohs(chunk->length) < sizeof(sctp_cookie_echo_t)) {
        return SCTP_DISPOSITION_BAD;
    }

    cookie = (sctp_cookie_echo_t *)((uint8_t *)chunk + sizeof(sctp_chunkhdr_t));

    if (!asoc->state_cookie || (ntohl(asoc->state_cookie->magic) != SCTP_COOKIE_MAGIC)) {
        return SCTP_DISPOSITION_DROP;
    }

    if (ntohl(asoc->state_cookie->v_tag) != asoc->verified_tag) {
        sctp_cmd_insert(commands, SCTP_CMD_COOKIE_ECHO_VTAG_MISMATCH);
        disposition = SCTP_DISPOSITION_RETRY;
        return disposition;
    }

    if (asoc->state == SCTP_STATE_COOKIE_ECHOED) {
        return SCTP_DISPOSITION_DROP;
    }

    sctp_cmd_insert(commands, SCTP_CMD_COOKIE_ECHO_PROCESS);

    return disposition;
}

sctp_disposition_t sctp_handle_dup_echo(struct net *net, const struct sctp_endpoint *ep,
                                        const struct sctp_association *asoc,
                                        sctp_subtype_t type, void *arg,
                                        sctp_cmd_seq_t *commands) {
    sctp_chunk_t *chunk = arg;
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;
    int error = 0;

    if (!chunk || chunk->chunk_hdr->length < sizeof(sctp_cookie_echo_chunk_t)) {
        return SCTP_DISPOSITION_BAD;
    }

    if (sctp_unpack_cookie(net, ep, asoc, chunk) < 0) {
        sctp_cmd_seq_add(commands, SCTP_CMD_ERROR, NULL);
        return SCTP_DISPOSITION_NOMEM;
    }

    if (asoc->peer.peer_verified) {
        if (asoc->peer.primary_path && asoc->peer.primary_path->rwnd != 0) {
            sctp_cmd_seq_add(commands, SCTP_CMD_INIT_RESTART, NULL);
        } else {
            sctp_cmd_seq_add(commands, SCTP_CMD_REPORT_ERROR, NULL);
            disposition = SCTP_DISPOSITION_DISCARD;
        }
    } else {
        sctp_cmd_seq_add(commands, SCTP_CMD_COOKIE_ECHO, NULL);
    }

    return disposition;
}

sctp_disposition_t sctp_handle_dup_cookie_echo(struct net *net,
                                              const struct sctp_endpoint *ep,
                                              const struct sctp_association *asoc,
                                              sctp_subtype_t type,
                                              void *arg,
                                              sctp_cmd_seq_t *commands)
{
    sctp_chunk_t *chunk = (sctp_chunk_t *)arg;
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;
    int error = 0;

    if (!chunk || chunk->chunk_hdr->length < sizeof(sctp_cookie_echo_chunk_t)) {
        return SCTP_DISPOSITION_BAD;
    }

    /* Decode the chunk and attempt to unpack the state cookie */
    if (!sctp_unpack_cookie(net, ep, asoc, chunk)) {
        disposition = SCTP_DISPOSITION_NOMEM;
        goto out;
    }

    /* Compare verification tags and handle association restart or collision */
    if (asoc->c.peer.init_tag != chunk->subh.cookie_echo_hdr->verification_tag) {
        sctp_cmd_t cmd;
        sctp_cmd_init(&cmd, SCTP_CMD_COOKIE_ECHO_MISMATCH, asoc);
        sctp_cmd_seq_add(commands, &cmd);
        disposition = SCTP_DISPOSITION_NOMEM;
    }

out:
    return disposition;
}
